#!/usr/bin/env node
// Generate the BYOD ("bring your own database") bootstrap from the migrations.
// Source of truth: supabase/migrations/*.sql (applied in filename order)
// Generated file:  supabase/byod/bootstrap.sql
//
//   node supabase/byod/generate.mjs          regenerate bootstrap.sql
//   node supabase/byod/generate.mjs --check  exit 1 if it is stale (CI)
//
// Why generated: bootstrap.sql used to be a hand-written SUBSET of the schema.
// The edge function kept moving with the migrations and the subset did not —
// by 00113 it defined 6 of the 48 RPCs the edge calls, and its `memory_write`
// still took `p_ttl_days` while both write paths send `p_ttl_seconds`, `p_kind`,
// `p_host` and `p_origin_*`. PostgREST resolves an RPC by argument NAME, so a
// BYOD database built from it misses the function entirely (PGRST202). A second
// hand-written copy of the schema drifts; a projection of the migrations cannot.
//
// The output is the migrations, verbatim and in order, inside ONE transaction:
//   * a guard refuses to run against a database that already holds the schema,
//     so a second paste into the SQL Editor fails closed instead of half-applying;
//   * every migration's version is recorded in Supabase's migration history
//     (`supabase_migrations.schema_migrations`), so a database bootstrapped from
//     this file upgrades with `supabase db push` like any linked project.
//
// Zero-dependency (node built-ins only), deterministic (no timestamps), so the
// --check comparison is a plain string equality.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const MIGRATIONS_DIR = path.join(ROOT, 'supabase/migrations');
export const OUTPUT_PATH = path.join(ROOT, 'supabase/byod/bootstrap.sql');

// The Supabase CLI's own migration filename grammar: `<digits>_<name>.sql`.
const MIGRATION_FILE = /^(\d+)_(.+)\.sql$/;

/**
 * Parse a migration filename into the (version, name) pair the Supabase CLI
 * records. Returns null for a file the CLI would not treat as a migration.
 */
export function parseMigrationName(file) {
  const m = MIGRATION_FILE.exec(file);
  return m ? { version: m[1], name: m[2] } : null;
}

/** Quote a value as a SQL string literal. */
function sqlLiteral(value) {
  return `'${String(value).replaceAll("'", "''")}'`;
}

function banner(text) {
  const rule = '-- ' + '─'.repeat(77);
  return `${rule}\n-- ${text}\n${rule}`;
}

/**
 * Render bootstrap.sql from an ordered list of migrations.
 * @param {{ file: string, sql: string }[]} migrations  already sorted by filename
 * @returns {string}
 */
export function renderBootstrap(migrations) {
  if (migrations.length === 0) throw new Error('no migrations to render');
  const parsed = migrations.map(({ file, sql }) => {
    const id = parseMigrationName(file);
    if (!id) throw new Error(`not a migration filename: ${file}`);
    return { file, sql: sql.endsWith('\n') ? sql : `${sql}\n`, ...id };
  });
  const newest = parsed[parsed.length - 1].file;

  const header = `-- LoreKit BYOD bootstrap schema
--
-- ⚠ GENERATED FILE — DO NOT EDIT BY HAND.
-- Generated by \`node supabase/byod/generate.mjs\` from the
-- ${parsed.length} migrations in supabase/migrations/ (newest: ${newest}).
-- CI fails when this file and the migrations disagree; edit a migration (or add
-- one) and regenerate instead.
--
-- What it does: applies the FULL LoreKit schema — the same migrations the hosted
-- project runs — to an empty Supabase project, in one transaction, and records
-- each migration in Supabase's migration history.
--
-- Fresh database only. A guard below aborts (and rolls everything back) when the
-- LoreKit schema is already present. Apply with ON_ERROR_STOP so psql stops at
-- the first error instead of carrying on past it:
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f supabase/byod/bootstrap.sql
--
-- or paste the whole file into the Supabase dashboard → SQL Editor and run it.
-- $DATABASE_URL is the connection string from the Supabase dashboard → Connect;
-- its password is the DATABASE password, not the service-role API key.
--
-- Upgrades: because the migration history is recorded, a later LoreKit release
-- upgrades the database with the Supabase CLI from a checkout of the repo:
--
--   supabase link --project-ref <your-storage-project-ref>
--   supabase db push
--
-- Billing: memories stored in your own database are NOT counted against
-- LoreKit's hosted memory-count billing — LoreKit has no visibility into it.
-- The memory cap and rate limit are read from \`lorekit_default_limit\` /
-- \`user_limits\` in YOUR database; adjust them there.
--
-- See docs/byod.md for the full setup.

begin;

-- Fail closed on a database that already holds the schema: re-running the
-- migrations from the top would collide with the existing objects partway
-- through. Raising here rolls back the transaction before anything changes.
do $guard$
begin
  if to_regclass('public.memories') is not null then
    raise exception using
      message = 'LoreKit schema already present: bootstrap.sql only initialises an empty database.',
      hint = 'Upgrade an existing BYOD database with \`supabase db push\` (see docs/byod.md).';
  end if;
end
$guard$;

-- The Supabase CLI's migration-history table. \`if not exists\` keeps this
-- compatible with a project the CLI has already touched; the CLI adds any
-- further columns it needs on its next run.
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (
  version text not null primary key,
  statements text[],
  name text
);
`;

  const body = parsed
    .map(
      ({ file, sql, version, name }) => `
${banner(file)}

${sql}
insert into supabase_migrations.schema_migrations (version, name)
values (${sqlLiteral(version)}, ${sqlLiteral(name)})
on conflict (version) do nothing;
`,
    )
    .join('');

  return `${header}${body}
commit;
`;
}

/** Read every migration in filename order. */
export function readMigrations(dir = MIGRATIONS_DIR) {
  return fs
    .readdirSync(dir)
    .filter((f) => parseMigrationName(f))
    .sort()
    .map((file) => ({ file, sql: fs.readFileSync(path.join(dir, file), 'utf8') }));
}

function main() {
  const expected = renderBootstrap(readMigrations());
  const rel = path.relative(ROOT, OUTPUT_PATH);

  if (process.argv.includes('--check')) {
    let actual = null;
    try {
      actual = fs.readFileSync(OUTPUT_PATH, 'utf8');
    } catch {
      // Missing file: reported as stale below.
    }
    if (actual !== expected) {
      console.error(`${rel} is out of date with supabase/migrations/.`);
      console.error('Run: node supabase/byod/generate.mjs');
      process.exit(1);
    }
    console.log(`${rel} matches supabase/migrations/.`);
    return;
  }

  fs.writeFileSync(OUTPUT_PATH, expected);
  console.log(`Wrote ${rel}.`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
